    'Sitede yayınlanan Aydınlatma Metni ve Açık Rıza Metnini zengin metin editörüyle düzenleyin.' => 'Խմբագրեք Գաղտնիության Ծանուցումը և Հստակ Համաձայնությունը:',
    'Sitedeki ana menü öğelerini sıralayın, yeni menü bağlantısı veya dikey ayraç ekleyin.' => 'Վերադասավորեք վերին մենյուի տարրերը, ավելացրեք հղումներ կամ բաժանիչներ:',
