    'Sitedeki tüm dilleri tek ekranda yan yana karşılaştırın, boş alanları tek tıkla otomatik çevirin ve topluca kaydedin.' => 'Համեմատեք կայքի բոլոր լեզուները մեկ էկրանին, մեկ սեղմումով ավտոմատ թարգմանեք դատարկ դաշտերը և պահպանեք:',
