    'Enter the addresses here. Choose whether icons appear in the header or footer under Themes › Customise › Menu / Footer.' => 'Մուտքագրեք հասցեներն այստեղ։ Պատկերակների՝ էջագլխում կամ էջատակում հայտնվելն ընտրեք Թեմաներ › Հարմարեցնել › Մենյու / Էջատակ բաժնում։',
    'Visibility:' => 'Տեսանելիություն՝',
