    'Upload logo files here. To choose how the logo appears in the header (emblem, full logo, name only, size):' => 'Վերբեռնեք լոգոյի ֆայլերն այստեղ։ Ընտրելու համար, թե ինչպես է լոգոն երևում էջագլխում (զինանշան, ամբողջական լոգո, միայն անուն, չափ)՝',
    'Header › Logo' => 'Էջագլուխ › Լոգո',
