    '"Always active" Label' => '«Միշտ ակտիվ» պիտակ',
    'Analytics Cookies Title' => 'Վերլուծական քուքիների վերնագիր',
    'Analytics Cookies Description' => 'Վերլուծական քուքիների նկարագրություն',
    'Policy Link Text' => 'Քաղաքականության հղման տեքստ',
    'Cookie Consent (KVKK / GDPR)' => 'Քուքիների համաձայնություն (KVKK / GDPR)',
    'Shows a banner asking visitors for their cookie choice on first visit. Works in all active languages.' => 'Առաջին այցի ժամանակ ցուցադրում է բաներ, որը հարցնում է այցելուների քուքիների ընտրությունը։ Աշխատում է բոլոր ակտիվ լեզուներով։',
    'Cookie Consent Banner' => 'Քուքիների համաձայնության բաներ',
    'When on, Google Analytics loads only after the visitor consents.' => 'Միացված լինելու դեպքում Google Analytics-ը բեռնվում է միայն այցելուի համաձայնությունից հետո։',
    'Layout' => 'Դասավորություն',
    'Box in bottom-left corner' => 'Տուփ ներքևի ձախ անկյունում',
    'Full-width bar at the bottom' => 'Ամբողջ լայնությամբ տող ներքևում',
    'How it works' => 'Ինչպես է աշխատում',
    '• "Accept" and "Reject" have equal weight; the analytics switch is off by default (KVKK Cookie Guide / GDPR).' => '• «Ընդունել» և «Մերժել» կոճակները հավասարազոր են. վերլուծության անջատիչը լռելյայն անջատված է (KVKK քուքիների ուղեցույց / GDPR)։',
    '• The visitor\'s choice is kept for 180 days and can be changed anytime via the "Cookie Preferences" footer link.' => '• Այցելուի ընտրությունը պահվում է 180 օր և ցանկացած պահի կարող է փոխվել էջատակի «Քուքիների նախընտրություններ» հղումով։',
    '• Google Analytics: ' => '• Google Analytics՝ ',
    'not set' => 'սահմանված չէ',
    'Consent version: ' => 'Համաձայնության տարբերակ՝ ',
    '• Empty text fields use the built-in translation for each language.' => '• Դատարկ տեքստային դաշտերն օգտագործում են յուրաքանչյուր լեզվի ներկառուցված թարգմանությունը։',
    'Banner Texts' => 'Բաների տեքստեր',
    'Policy Link (defaults to Privacy Notice page)' => 'Քաղաքականության հղում (լռելյայն՝ Գաղտնիության ծանուցման էջը)',
    'If you changed the texts or how cookies are used, you can show the banner again to visitors who already decided.' => 'Եթե փոխել եք տեքստերը կամ քուքիների օգտագործման ձևը, կարող եք բաները կրկին ցուցադրել այն այցելուներին, ովքեր արդեն որոշում են կայացրել։',
    'Show the cookie banner to all visitors again?' => 'Կրկին ցուցադրե՞լ քուքիների բաները բոլոր այցելուներին',
    'Show again' => 'Ցուցադրել կրկին',
    'Ask Everyone Again' => 'Կրկին հարցնել բոլորին',
    'Google Services' => 'Google ծառայություններ',
    'Keys used for visitor statistics and maps. Leave them as they are if unsure.' => 'Այցելուների վիճակագրության և քարտեզների համար օգտագործվող բանալիներ։ Եթե վստահ չեք, թողեք ինչպես կան։',
    'Google Analytics Measurement ID' => 'Google Analytics չափման ID',
    'Adds visitor tracking. If cookie consent is on, it only runs for visitors who accept.' => 'Ավելացնում է այցելուների հետագծում։ Եթե քուքիների համաձայնությունը միացված է, այն աշխատում է միայն համաձայնած այցելուների համար։',
    'Statistics Connection (GA4 Property ID & Service Account)' => 'Վիճակագրության կապ (GA4 Property ID և ծառայողական հաշիվ)',
    'Lets the Statistics page fetch data from Google. Set up there, with a connection test and JSON file upload.' => 'Թույլ է տալիս Վիճակագրություն էջին տվյալներ ստանալ Google-ից։ Կարգավորվում է այնտեղ՝ կապի ստուգմամբ և JSON ֆայլի վերբեռնմամբ։',
    'Connection Settings' => 'Կապի կարգավորումներ',
    'For the map on the contact page.' => 'Կապի էջի քարտեզի համար։',
    'Image Converter (AVIF / WebP)' => 'Պատկերների փոխարկիչ (AVIF / WebP)',
    'Generates next-gen AVIF/WebP formats and responsive thumbnails.' => 'Ստեղծում է նոր սերնդի AVIF/WebP ձևաչափեր և հարմարվողական մանրապատկերներ։',
    'Open Converter →' => 'Բացել փոխարկիչը →',
    'Panel language and site languages:' => 'Վահանակի լեզուն և կայքի լեզուները՝',
    'Cinematic Dark' => 'Կինեմատոգրաֆիկ մուգ',
    'Most Popular' => 'Ամենատարածվածը',
    'Deep black darkroom ambience (#000000), full-screen imagery, and fluid horizontal navigation.' => 'Խոր սև լուսանկարչական մութ սենյակի մթնոլորտ (#000000), ամբողջ էկրանով պատկերներ և սահուն հորիզոնական նավիգացիա։',
    'Dark Black (#000000)' => 'Խոր սև (#000000)',
    'Full-Bleed Cinematic Slide' => 'Ամբողջ կադրով կինեմատոգրաֆիկ սլայդ',
    'Right Visual Spread' => 'Տեսողական բացվածք աջում',
    'Horizontal Classic Nav' => 'Դասական հորիզոնական նավիգացիա',
    'Pure White Cube Gallery' => 'Մաքուր սպիտակ White Cube պատկերասրահ',
    'Pure White & Minimal' => 'Մաքուր սպիտակ և մինիմալ',
    'Modern contemporary gallery aesthetic in stark pure white (#FFFFFF), preserving original aspect ratios in white cube spreads with dark typography.' => 'Ժամանակակից պատկերասրահի գեղագիտություն մաքուր սպիտակով (#FFFFFF)՝ պահպանելով բնօրինակ համամասնությունները white cube բացվածքներում՝ մուգ տառատեսակով։',
    'Pure White (#FFFFFF)' => 'Մաքուր սպիտակ (#FFFFFF)',
    'White Cube Gallery' => 'White Cube պատկերասրահ',
    'White Cube Exhibition' => 'White Cube ցուցադրություն',
    'Horizontal Left Menu' => 'Հորիզոնական մենյու ձախում',
    'Editorial Magazine & Essay' => 'Խմբագրական ամսագիր և էսսե',
    'Editorial' => 'Խմբագրական',
    'Strong typographic hierarchy, large covers, two-column magazine spreads, and narrative photo-essay rhythm.' => 'Ուժեղ տպագրական հիերարխիա, մեծ շապիկներ, երկսյուն ամսագրային բացվածքներ և ֆոտոէսսեի պատումային ռիթմ։',
    'Dark Charcoal (#0A0C10)' => 'Մուգ ածխագույն (#0A0C10)',
    'Editorial Magazine Cover' => 'Խմբագրական ամսագրի շապիկ',
    'Magazine Article Spread' => 'Ամսագրի հոդվածի բացվածք',
    'Museum Paper & Passepartout' => 'Թանգարանային թուղթ և պասպարտու',
    'Art Book Texture' => 'Արվեստի գրքի ֆակտուրա',
    'Warm archival cream paper (#F4F2ED), symmetric passepartout borders, and curatorial exhibition labels.' => 'Տաք կրեմագույն արխիվային թուղթ (#F4F2ED), համաչափ պասպարտուի լուսանցքներ և կուրատորական ցուցահանդեսային պիտակներ։',
    'Warm Cream Paper (#F4F2ED)' => 'Տաք կրեմագույն թուղթ (#F4F2ED)',
    'Centered Museum Spread' => 'Կենտրոնացված թանգարանային բացվածք',
    'Contemporary Vertical Monograph' => 'Ժամանակակից ուղղահայաց մենագրություն',
    'Monograph' => 'Մենագրություն',
    'Fixed left vertical sidebar navigation, monograph chapters, and continuous visual exhibition wall.' => 'Ֆիքսված ուղղահայաց կողային նավիգացիա ձախում, մենագրության գլուխներ և անընդհատ տեսողական ցուցադրության պատ։',
    'Vertical Story Chapters' => 'Պատմության ուղղահայաց գլուխներ',
    'Sticky Split Monograph' => 'Ֆիքսված բաժանված մենագրություն',
    'Left Vertical Menu' => 'Ուղղահայաց մենյու ձախում',
    'Sidebar List' => 'Կողային վահանակի ցանկ',
    'New · Minimal' => 'Նոր · Մինիմալ',
    'White background, project list on the left and one large uncropped photo on the right; captioned sequence on project pages. For a few strong projects.' => 'Սպիտակ ֆոն, նախագծերի ցանկ ձախում և մեկ մեծ չկտրված լուսանկար աջում. նախագծի էջերում՝ մակագրված հաջորդականություն։ Մի քանի ուժեղ նախագծերի համար։',
    'White' => 'Սպիտակ',
    'Captioned Sequence' => 'Մակագրված հաջորդականություն',
    'Left-Aligned Top Bar' => 'Ձախ հավասարեցված վերին տող',
    'Map Atlas' => 'Քարտեզների ատլաս',
    'New · Documentary' => 'Նոր · Վավերագրական',
    'Projects on a world map on the homepage, archive by year in the portfolio, captioned sequence on project pages. For work across many places.' => 'Նախագծեր աշխարհի քարտեզի վրա՝ գլխավոր էջում, արխիվ ըստ տարիների՝ պորտֆոլիոյում, մակագրված հաջորդականություն՝ նախագծի էջերում։ Բազմաթիվ վայրերում կատարված աշխատանքի համար։',
    'Dark' => 'Մուգ',
    'Project Map' => 'Նախագծերի քարտեզ',
    'Classic Top Bar' => 'Դասական վերին տող',
    'Archive' => 'Արխիվ',
    'New · Archive' => 'Նոր · Արխիվ',
    'Archive by year on the homepage, contact sheet in the portfolio, two-column gallery on project pages. For many projects over many years.' => 'Արխիվ ըստ տարիների՝ գլխավոր էջում, կոնտակտային թերթ՝ պորտֆոլիոյում, երկսյուն պատկերասրահ՝ նախագծի էջերում։ Երկար տարիների բազմաթիվ նախագծերի համար։',
    'Archive by Year' => 'Արխիվ ըստ տարիների',
    'Two-Column Gallery' => 'Երկսյուն պատկերասրահ',
    'Photobook' => 'Ֆոտոգիրք',
    'New · Book' => 'Նոր · Գիրք',
    'Cream paper background; photo and short statement on the homepage, free collage in the portfolio, book-like spreads on project pages.' => 'Կրեմագույն թղթի ֆոն. լուսանկար և կարճ տեքստ՝ գլխավոր էջում, ազատ կոլաժ՝ պորտֆոլիոյում, գրքանման բացվածքներ՝ նախագծի էջերում։',
    'Cream Paper' => 'Կրեմագույն թուղթ',
    'Photo + Statement' => 'Լուսանկար + տեքստ',
    'Photobook Spread' => 'Ֆոտոգրքի բացվածք',
    'Agency Showcase' => 'Գործակալության ցուցափեղկ',
    'New · Showcase' => 'Նոր · Ցուցափեղկ',
    'Full-screen cover, selected work, latest writing and a contact call on the homepage; curatorial grid in the portfolio. Gives editors and clients a quick overview.' => 'Ամբողջ էկրանով շապիկ, ընտրված աշխատանքներ, վերջին գրառումներ և կապի կոչ՝ գլխավոր էջում. կուրատորական ցանց՝ պորտֆոլիոյում։ Խմբագիրներին և պատվիրատուներին տալիս է արագ պատկերացում։',
    'Sectioned Showcase' => 'Բաժիններով ցուցափեղկ',
    'Cinematic Cover' => 'Կինեմատոգրաֆիկ շապիկ',
    'Transparent Top Bar' => 'Թափանցիկ վերին տող',
    'Unpublished changes discarded.' => 'Չհրապարակված փոփոխությունները չեղարկվեցին։',
    'No changes to publish.' => 'Հրապարակելու փոփոխություններ չկան։',
    'Page design published; the rest of the site is unchanged. Use “Revert to previous look” to undo.' => 'Էջի դիզայնը հրապարակվեց. կայքի մնացած մասն անփոփոխ է։ Չեղարկելու համար օգտագործեք «Վերադառնալ նախորդ տեսքին»։',
    '“%s” theme published. Use “Revert to previous look” to undo.' => '«%s» թեման հրապարակվեց։ Չեղարկելու համար օգտագործեք «Վերադառնալ նախորդ տեսքին»։',
    'Security check failed (CSRF).' => 'Անվտանգության ստուգումը ձախողվեց (CSRF)։',
    'Look before applying “%s”' => 'Դիտեք՝ նախքան «%s»-ը կիրառելը',
    '“%s” applied. Use “Revert to previous look” to undo.' => '«%s»-ը կիրառվեց։ Չեղարկելու համար օգտագործեք «Վերադառնալ նախորդ տեսքին»։',
    'Reverted to the previous look.' => 'Վերադարձվեց նախորդ տեսքին։',
    'Template options saved.' => 'Կաղապարի ընտրանքները պահպանվեցին։',
    'Click a theme to see what it offers, preview it with your own photographs, customise its colours, logo and menu, and publish.' => 'Սեղմեք թեմայի վրա՝ տեսնելու, թե ինչ է այն առաջարկում, նախադիտեք ձեր սեփական լուսանկարներով, հարմարեցրեք գույները, լոգոն և մենյուն և հրապարակեք։',
    '“%s” is being previewed in your browser only; the site has not changed for visitors.' => '«%s»-ը նախադիտվում է միայն ձեր դիտարկիչում. այցելուների համար կայքը չի փոխվել։',
    '“%s” was applied on %s. If you don’t like it, revert to the previous look in one click.' => '«%s»-ը կիրառվել է %s-ին։ Եթե չեք հավանում, մեկ սեղմումով վերադարձեք նախորդ տեսքին։',
    'Revert the site to the look it had before this template?' => 'Վերադարձնե՞լ կայքն այն տեսքին, որն ուներ մինչ այս կաղապարը',
