    'The preview on the right uses your own photographs and is shown only to you. Visitors see no change until you press “Publish”.' => 'Աջ կողմի նախադիտումն օգտագործում է ձեր սեփական լուսանկարները և ցուցադրվում է միայն ձեզ։ Այցելուները փոփոխություն չեն տեսնում, մինչև չսեղմեք «Հրապարակել»։',
