    'Publish the changes? Shared settings apply site-wide; page settings apply only to: %s. You can revert in one click.' => 'Հրապարակե՞լ փոփոխությունները։ Ընդհանուր կարգավորումները կիրառվում են ամբողջ կայքում, էջի կարգավորումները՝ միայն՝ %s։ Կարող եք վերադարձնել մեկ սեղմումով։',
    'Publish the “%s” theme with these settings to the whole site? You can revert in one click.' => 'Հրապարակե՞լ «%s» թեման այս կարգավորումներով ամբողջ կայքում։ Կարող եք վերադարձնել մեկ սեղմումով։',
    'Discard all unpublished changes?' => 'Չեղարկե՞լ բոլոր չհրապարակված փոփոխությունները',
