    'Every text setting on your site, section by section.' => 'Ձեր կայքի յուրաքանչյուր տեքստային կարգավորումը՝ բաժին առ բաժին։',
    'Change the main colours of your site quickly, in one place.' => 'Արագ փոխեք ձեր կայքի հիմնական գույները՝ մեկ տեղում։',
    'Change all the fonts on your site quickly, in one place.' => 'Արագ փոխեք ձեր կայքի բոլոր տառատեսակները՝ մեկ տեղում։',
    'Enter a valid link: https://…, /page/ or mailto:…' => 'Մուտքագրեք վավեր հղում՝ https://…, /page/ կամ mailto:…',
    'This tone is too dark. Pick a light tone, or use “Black” for a dark site.' => 'Այս երանգը չափազանց մուգ է։ Ընտրեք բաց երանգ կամ մուգ կայքի համար օգտագործեք «Սև»-ը։',
    'Which page' => 'Որ էջը',
    'All lists (shared)' => 'Բոլոր ցանկերը (ընդհանուր)',
    'All project pages (shared)' => 'Նախագծերի բոլոր էջերը (ընդհանուր)',
    'own settings' => 'սեփական կարգավորումներ',
    'Settings here apply to every page that has no settings of its own.' => 'Այստեղի կարգավորումները կիրառվում են յուրաքանչյուր էջի համար, որը չունի սեփական կարգավորումներ։',
    'This page uses the shared settings. To give it its own layout and settings:' => 'Այս էջն օգտագործում է ընդհանուր կարգավորումները։ Նրան սեփական դասավորություն և կարգավորումներ տալու համար՝',
    'Give this page its own settings' => 'Տալ այս էջին սեփական կարգավորումներ',
    'This page has its own settings; changes to the shared settings do not affect it.' => 'Այս էջն ունի սեփական կարգավորումներ. ընդհանուր կարգավորումների փոփոխությունները նրա վրա չեն ազդում։',
    'Use shared settings' => 'Օգտագործել ընդհանուր կարգավորումները',
