    'Numbered project list on the left, one large uncropped photo on the right; hovering the list switches the photo. Best for a few strong projects.' => 'Նախագծերի համարակալված ցանկ ձախում, մեկ մեծ չկտրված լուսանկար աջում. ցանկի վրա նշիչը պահելիս լուսանկարը փոխվում է։ Լավագույնն է մի քանի ուժեղ նախագծերի համար։',
    '14. Archive by Year' => '14. Արխիվ ըստ տարիների',
    'Projects grouped under year headings with thumbnail, title and place. Best for a long, multi-project archive.' => 'Նախագծերը խմբավորված են տարիների վերնագրերի տակ՝ մանրապատկերով, վերնագրով և վայրով։ Լավագույնն է բազմաթիվ նախագծերով երկար արխիվի համար։',
    '15. Contact Sheet' => '15. Կոնտակտային թերթ',
    'All works as small numbered frames on black, like a film contact sheet; frames enlarge on hover. Best for many works.' => 'Բոլոր աշխատանքները՝ որպես փոքր համարակալված կադրեր սևի վրա, ինչպես ժապավենի կոնտակտային թերթ. նշիչը պահելիս կադրերը մեծանում են։ Լավագույնն է շատ աշխատանքների համար։',
    '16. Photo + Statement' => '16. Լուսանկար + տեքստ',
    'One large photo on one side, a short statement in large type and the project list on the other. The text comes from the site description in Site Settings › General.' => 'Մի կողմում՝ մեկ մեծ լուսանկար, մյուսում՝ կարճ տեքստ մեծ տառերով և նախագծերի ցանկը։ Տեքստը վերցվում է կայքի նկարագրությունից՝ Կայքի կարգավորումներ › Ընդհանուր բաժնից։',
    '17. Project Map' => '17. Նախագծերի քարտեզ',
    'Each project as a point on a world map where it was shot; clicking shows the cover and link. Project list alongside. Places are found from each project’s Location field.' => 'Յուրաքանչյուր նախագիծ՝ որպես կետ աշխարհի քարտեզի վրա՝ նկարահանման վայրում. սեղմելիս ցուցադրվում են շապիկը և հղումը։ Կողքին՝ նախագծերի ցանկը։ Վայրերը որոշվում են յուրաքանչյուր նախագծի Վայր դաշտից։',
    '18. Sectioned Showcase' => '18. Բաժիններով ցուցափեղկ',
    'Full-screen cover, then Selected Work cards, latest blog posts (if blog is on), a short intro and About / Contact links. Everything on one page.' => 'Ամբողջ էկրանով շապիկ, ապա ընտրված աշխատանքների քարտեր, բլոգի վերջին գրառումները (եթե բլոգը միացված է), կարճ ներածություն և Իմ մասին / Կապ հղումներ։ Ամեն ինչ մեկ էջում։',
    '20. Thumbnail Grid' => '20. Մանրապատկերների ցանց',
    'All work as small thumbnails side by side; titles on hover. Looks best with the sidebar menu. Columns and cropping are chosen on the Templates page.' => 'Բոլոր աշխատանքները՝ որպես փոքր մանրապատկերներ կողք կողքի. վերնագրերը՝ նշիչը պահելիս։ Լավագույնս երևում է կողային մենյուի հետ։ Սյունակները և կտրումն ընտրվում են Կաղապարներ էջում։',
    '21. Photobook Spreads' => '21. Ֆոտոգրքի բացվածքներ',
    'Work laid out as two-page book spreads on warm paper; the first page shows the site name and description. Page by page on phones.' => 'Աշխատանքները դասավորված են որպես երկէջանի գրքային բացվածքներ տաք թղթի վրա. առաջին էջում՝ կայքի անվանումը և նկարագրությունը։ Հեռախոսներում՝ էջ առ էջ։',
    '22. Mosaic Wall' => '22. Խճանկարային պատ',
    'Covers of varying sizes form a dense wall; titles on hover. Columns are chosen on the Templates page.' => 'Տարբեր չափերի շապիկները կազմում են խիտ պատ. վերնագրերը՝ նշիչը պահելիս։ Սյունակներն ընտրվում են Կաղապարներ էջում։',
    '23. Photo Wall' => '23. Լուսանկարների պատ',
    'Photos stacked uncropped in columns at their natural proportions, titles below. Set the column count in Themes › Customise › Homepage. Best for: series that mix portrait and landscape photos.' => 'Լուսանկարները՝ չկտրված, սյունակներով՝ իրենց բնական համամասնություններով, վերնագրերը՝ ներքևում։ Սյունակների քանակը սահմանեք Թեմաներ › Հարմարեցնել › Գլխավոր էջ բաժնում։ Լավագույնն է՝ ուղղահայաց և հորիզոնական լուսանկարներ համադրող շարքերի համար։',
    '24. Staggered Gallery' => '24. Շեղված պատկերասրահ',
    'Uncropped photos in varying widths and offsets with generous space. Best for: calm selections that should feel like a gallery wall.' => 'Չկտրված լուսանկարներ՝ տարբեր լայնություններով և շեղումներով, առատ տարածությամբ։ Լավագույնն է՝ հանգիստ ընտրանիների համար, որոնք պետք է հիշեցնեն պատկերասրահի պատ։',
    '25. One Large, Two Small' => '25. Մեկ մեծ, երկու փոքր',
    'Blocks of three: one large and two small photos, the large one alternating sides. Best for: projects with strong cover photos.' => 'Եռյակներ՝ մեկ մեծ և երկու փոքր լուսանկար, մեծը հերթով փոխում է կողմը։ Լավագույնն է՝ ուժեղ շապիկի լուսանկարներ ունեցող նախագծերի համար։',
    '26. Featured + Grid' => '26. Առանձնացված + ցանց',
    'The first work large and uncropped, then small square thumbnails. Best for: when you want to lead with one recent work.' => 'Առաջին աշխատանքը՝ մեծ և չկտրված, ապա փոքր քառակուսի մանրապատկերներ։ Լավագույնն է՝ երբ ուզում եք սկսել վերջին աշխատանքներից մեկով։',
    '27. Zigzag Stream' => '27. Զիգզագ հոսք',
    'Uncropped photos flow down the page, alternating left and right, titles below. Best for: strong single frames worth a long look.' => 'Չկտրված լուսանկարները հոսում են էջով ներքև՝ հերթով ձախ և աջ, վերնագրերը՝ ներքևում։ Լավագույնն է՝ ուժեղ առանձին կադրերի համար, որոնք արժանի են երկար հայացքի։',
    '28. Split Screens' => '28. Բաժանված էկրաններ',
    'Each project fills a screen: photo on one half, title and short text on the other, sides alternating. Choose edge-to-edge or framed (magazine) style.' => 'Յուրաքանչյուր նախագիծ զբաղեցնում է մեկ էկրան՝ մի կեսում լուսանկար, մյուսում՝ վերնագիր և կարճ տեքստ, կողմերը հերթափոխվում են։ Ընտրեք եզրից եզր կամ շրջանակով (ամսագրային) ոճը։',
    '29. Three Panels' => '29. Երեք վահանակ',
    'The screen splits into three tall panels, each a project cover with its name centred. Stacked on phones. Best for: portfolios with three to six main projects.' => 'Էկրանը բաժանվում է երեք բարձր վահանակի, յուրաքանչյուրը՝ նախագծի շապիկ՝ անվանումը կենտրոնում։ Հեռախոսներում՝ մեկը մյուսի տակ։ Լավագույնն է՝ երեքից վեց հիմնական նախագիծ ունեցող պորտֆոլիոների համար։',
    '30. Section Banners' => '30. Բաժինների բաներներ',
    'Each menu section becomes a wide banner with a cover photo, large title and an arrow. Shows sections on the homepage and projects on project lists.' => 'Մենյուի յուրաքանչյուր բաժին դառնում է լայն բաներ՝ շապիկի լուսանկարով, մեծ վերնագրով և սլաքով։ Գլխավոր էջում ցուցադրում է բաժինները, նախագծերի ցանկերում՝ նախագծերը։',
    '31. Light Table' => '31. Լուսային սեղան',
    'One large photo with a vertical thumbnail strip on the right; click a thumbnail (or use the arrow keys) to change the photo. On phones the strip moves below. Best for: showing photos one at a time on a dark background.' => 'Մեկ մեծ լուսանկար՝ աջում մանրապատկերների ուղղահայաց ժապավենով. լուսանկարը փոխելու համար սեղմեք մանրապատկերի վրա (կամ օգտագործեք սլաքների ստեղները)։ Հեռախոսներում ժապավենը տեղափոխվում է ներքև։ Լավագույնն է՝ լուսանկարները մեկ առ մեկ մուգ ֆոնի վրա ցուցադրելու համար։',
    '19. Free Collage' => '19. Ազատ կոլաժ',
    'Photos placed freely in varied sizes and positions without a grid; titles appear on hover. Single column on phones. For artistic and personal work.' => 'Լուսանկարները տեղադրված են ազատ՝ տարբեր չափերով և դիրքերով, առանց ցանցի. վերնագրերը հայտնվում են նշիչը պահելիս։ Հեռախոսներում՝ մեկ սյունակ։ Գեղարվեստական և անձնական աշխատանքների համար։',
    'You have unsaved changes' => 'Դուք ունեք չպահպանված փոփոխություններ',
    'Discard' => 'Չեղարկել',
    'Unlisted' => 'Ցանկից դուրս',
    'View on site' => 'Դիտել կայքում',
    'Save (Ctrl+S)' => 'Պահպանել (Ctrl+S)',
    'Homepage slide' => 'Գլխավոր էջի սլայդ',
    'Site settings / design' => 'Կայքի կարգավորումներ / դիզայն',
    'CSRF security verification failed.' => 'CSRF անվտանգության ստուգումը ձախողվեց։',
    'All page names, URL slugs, and top menu links have been updated.' => 'Բոլոր էջերի անվանումները, URL slug-ները և վերին մենյուի հղումները թարմացվեցին։',
    'Customize page names and permalinks. Changes automatically sync across panel templates, sidebars, and public navigation.' => 'Հարմարեցրեք էջերի անվանումները և մշտական հղումները։ Փոփոխություններն ավտոմատ համաժամացվում են վահանակի կաղապարներում, կողային վահանակներում և հանրային նավիգացիայում։',
    'Select Language to Edit:' => 'Ընտրեք խմբագրման լեզուն՝',
    '1. Portfolio Main Name & Categories' => '1. Պորտֆոլիոյի հիմնական անվանում և կատեգորիաներ',
    'Changing the Portfolio main name will automatically update all templates and panel sidebar links.' => 'Պորտֆոլիոյի հիմնական անվանումը փոխելիս բոլոր կաղապարները և վահանակի կողային հղումները ավտոմատ թարմացվում են։',
    'Portfolio Manager →' => 'Պորտֆոլիոյի կառավարում →',
    'Section / Category' => 'Բաժին / Կատեգորիա',
    'Display Name (Menu & Title)' => 'Ցուցադրվող անվանում (մենյու և վերնագիր)',
    'Page address' => 'Էջի հասցե',
    'Portfolio Name in Admin Menu' => 'Պորտֆոլիոյի անվանումը ադմինի մենյուում',
    'Shown only in the admin sidebar' => 'Ցուցադրվում է միայն ադմինի կողային վահանակում',
    'Not shown on the site' => 'Չի ցուցադրվում կայքում',
    '2. Static Pages (Blog, About, Contact etc.)' => '2. Ստատիկ էջեր (Բլոգ, Իմ մասին, Կապ և այլն)',
    'Rename pages to anything you like. The top menu updates automatically.' => 'Վերանվանեք էջերն ինչպես ցանկանում եք։ Վերին մենյուն թարմացվում է ավտոմատ։',
    'Page Type' => 'Էջի տեսակ',
    'Homepage Root' => 'Գլխավոր էջի արմատ',
    'Image Converter' => 'Պատկերների փոխարկիչ',
    'Generates fast-loading AVIF and WebP versions and smaller sizes of uploaded photos.' => 'Ստեղծում է վերբեռնված լուսանկարների արագ բեռնվող AVIF և WebP տարբերակներ և ավելի փոքր չափեր։',
    'High Depth & Engagement' => 'Բարձր խորություն և ներգրավվածություն',
    'Photo reading time' => 'Լուսանկարի դիտման ժամանակ',
    'Portfolio & Stories' => 'Պորտֆոլիո և պատմություններ',
    'Per user' => 'Մեկ օգտատիրոջ հաշվով',
    'Unique visits' => 'Եզակի այցեր',
    'Desktop (Editorial / Jury)' => 'Համակարգիչ (խմբագրական / ժյուրի)',
    'Avg.' => 'Միջ.',
    'Curators, jury, and editors review on large displays' => 'Կուրատորները, ժյուրին և խմբագիրները դիտում են մեծ էկրաններով',
    'Large Display Review' => 'Դիտում մեծ էկրանով',
    'Mobile (Social Discovery)' => 'Բջջային (սոցիալական հայտնաբերում)',
    'Instagram & X Entrances' => 'Մուտքեր Instagram-ից և X-ից',
    'Views' => 'Դիտումներ',
    'Unique' => 'Եզակի',
    'Share' => 'Կիսվել',
    'GA4 Property ID' => 'GA4 Property ID',
