    'New article' => 'Նոր հոդված',
    'Shown when an address is not found. Write the title and text in each language; if you set it to draft, the default text is shown.' => 'Ցուցադրվում է, երբ հասցեն չի գտնվում։ Գրեք վերնագիրը և տեքստը յուրաքանչյուր լեզվով. եթե այն դարձնեք սևագիր, ցուցադրվում է լռելյայն տեքստը։',
    'Write a title and build the content in the editor below. The page appears at its own address as a simple text page.' => 'Գրեք վերնագիր և կառուցեք բովանդակությունը ստորև բերված խմբագրիչում։ Էջը հայտնվում է իր սեփական հասցեով՝ որպես պարզ տեքստային էջ։',
    'Publish your essay, field note or news in several languages.' => 'Հրապարակեք ձեր էսսեն, դաշտային նշումը կամ նորությունը մի քանի լեզվով։',
