    'Fields containing MYMEMORY WARNING found in this language. You can clear them with one click.' => 'Այս լեզվում հայտնաբերվել են MYMEMORY WARNING պարունակող դաշտեր։ Կարող եք մաքրել դրանք մեկ սեղմումով։',
    'Clear Error Warnings Now' => 'Մաքրել սխալի նախազգուշացումները հիմա',
