    'Your own light tone instead of white, paper or gray. Dark tones are not accepted; choose “Black” for a dark site.' => 'Ձեր սեփական բաց երանգը՝ սպիտակի, թղթի կամ մոխրագույնի փոխարեն։ Մուգ երանգներ չեն ընդունվում. մուգ կայքի համար ընտրեք «Սև»։',
    'Text colour' => 'Տեքստի գույն',
    'Colour of headings, paragraphs and lists. Text over photographs is unchanged. Returns to automatic if a visitor switches light/dark.' => 'Վերնագրերի, պարբերությունների և ցանկերի գույնը։ Լուսանկարների վրայի տեքստը չի փոխվում։ Վերադառնում է ավտոմատին, եթե այցելուն փոխի բաց/մուգ ռեժիմը։',
