    'When the page scrolls' => 'Երբ էջը ոլորվում է',
    'How the menu behaves on inner pages. “On scroll up”: hides going down, reappears going up.' => 'Ինչպես է մենյուն իրեն պահում ներքին էջերում։ «Վերև ոլորելիս»՝ թաքնվում է ներքև ոլորելիս և կրկին հայտնվում վերև ոլորելիս։',
