    'Cards: equal boxes with the title over the photo. Uncropped: natural proportions with the title below. Full height: screen-tall with no gaps.' => 'Քարտեր՝ հավասար տուփեր, վերնագիրը լուսանկարի վրա։ Չկտրված՝ բնական համամասնություններ, վերնագիրը ներքևում։ Ամբողջ բարձրությամբ՝ էկրանի բարձրությամբ, առանց բացատների։',
    'Intro text above' => 'Ներածական տեքստ վերևում',
