    'Split screen style' => 'Բաժանված էկրանի ոճ',
    'Edge to edge: the photo fills half the screen. Framed: the photo sits on a tinted panel, like a magazine page. Project lists use the same style.' => 'Եզրից եզր՝ լուսանկարը լցնում է էկրանի կեսը։ Շրջանակով՝ լուսանկարը գտնվում է երանգավորված վահանակի վրա, ինչպես ամսագրի էջում։ Նախագծերի ցանկերն օգտագործում են նույն ոճը։',
    'Banners show' => 'Բաներներում ցուցադրվում են',
