    'Three tall project panels across the screen' => 'Նախագծերի երեք բարձր վահանակ էկրանի ողջ լայնությամբ',
    'The same panels in rows of three' => 'Նույն վահանակները՝ երեքական շարքերով',
    'A full-screen opening, then a captioned sequence' => 'Ամբողջ էկրանով բացում, ապա մակագրված հաջորդականություն',
    'Portfolios with three to six main projects' => 'Երեքից վեց հիմնական նախագիծ ունեցող պորտֆոլիոներ',
    'A wide banner for each menu section' => 'Լայն բաներ մենյուի յուրաքանչյուր բաժնի համար',
    'Projects as banners, one below another' => 'Նախագծեր՝ որպես բաներներ, մեկը մյուսի տակ',
    'Work organised into a few main sections' => 'Մի քանի հիմնական բաժինների բաժանված աշխատանք',
    'One large photo with a thumbnail strip on the right' => 'Մեկ մեծ լուսանկար՝ աջում մանրապատկերների ժապավենով',
    'The same light table with project covers' => 'Նույն լուսային սեղանը՝ նախագծերի շապիկներով',
    'A full-screen opening, then a gallery wall' => 'Ամբողջ էկրանով բացում, ապա պատկերասրահային պատ',
    'Showing photos one at a time on a dark background' => 'Լուսանկարները մեկ առ մեկ մուգ ֆոնի վրա ցուցադրելու համար',
    'Bottom right on the homepage, top on inner pages' => 'Գլխավոր էջում՝ ներքևում աջ, ներքին էջերում՝ վերևում',
    'A fullscreen slideshow without captions' => 'Ամբողջ էկրանով սլայդ-շոու՝ առանց մակագրերի',
    'A full-screen opening, then photos one by one' => 'Ամբողջ էկրանով բացում, ապա լուսանկարներ մեկ առ մեկ',
    'Letting the photo fill the screen uninterrupted' => 'Թույլ տալ լուսանկարին անխափան լցնել էկրանը',
    'Sidebar + Thumbnail Grid' => 'Կողային վահանակ + մանրապատկերների ցանց',
    'Fixed name and menu on the left; all work as small thumbnails side by side.' => 'Ֆիքսված անուն և մենյու ձախում. բոլոր աշխատանքները՝ փոքր մանրապատկերներով կողք կողքի։',
    'Sidebar + Single Image' => 'Կողային վահանակ + մեկ պատկեր',
    'Name and menu on the left; one large uncropped image on a plain background.' => 'Անունը և մենյուն ձախում. մեկ մեծ, չկտրված պատկեր՝ պարզ ֆոնի վրա։',
    'Top Menu + Fullscreen Slideshow' => 'Վերին մենյու + ամբողջ էկրանով սլայդ-շոու',
    'Menu over the image; one fullscreen photo per screen with its title.' => 'Մենյուն պատկերի վրա. մեկ էկրանին՝ մեկ ամբողջ էկրանով լուսանկար՝ իր վերնագրով։',
    'Tiled Grid' => 'Սալիկային ցանց',
    'Project covers in equal tiles under a top menu; titles on hover.' => 'Նախագծերի շապիկներ հավասար սալիկներով՝ վերին մենյուի տակ. վերնագրերը՝ նշիչը պահելիս։',
    'Horizontal Strip' => 'Հորիզոնական ժապավեն',
    'Uncropped images at equal height in a sideways-scrolling row.' => 'Չկտրված պատկերներ հավասար բարձրությամբ՝ կողային ոլորվող շարքում։',
    'Vertical Stream' => 'Ուղղահայաց հոսք',
    'Large images flowing down the page with titles and short text between them.' => 'Մեծ պատկերներ էջով ներքև՝ դրանց միջև վերնագրերով և կարճ տեքստով։',
    'Text Index' => 'Տեքստային ցանկ',
    'A large name and a project list; a small preview appears on hover.' => 'Մեծ անուն և նախագծերի ցանկ. նշիչը պահելիս հայտնվում է փոքր նախադիտում։',
    'Mosaic Wall' => 'Խճանկարային պատ',
    'Covers of varying sizes form a dense wall; titles on hover.' => 'Տարբեր չափերի շապիկները կազմում են խիտ պատ. վերնագրերը՝ նշիչը պահելիս։',
    'Projects grouped under year headings with a small cover, title and place.' => 'Նախագծերը խմբավորված են տարիների վերնագրերի տակ՝ փոքր շապիկով, վերնագրով և վայրով։',
    'Warm paper background; projects laid out as two-page book spreads.' => 'Տաք թղթի ֆոն. նախագծերը դասավորված են երկէջանի գրքային բացվածքներով։',
    'Top Menu + Square Grid' => 'Վերին մենյու + քառակուսի ցանց',
    'Name on the left, menu on the right; all work below in a centred grid of equal square thumbnails.' => 'Անունը ձախում, մենյուն աջում. բոլոր աշխատանքները ներքևում՝ հավասար քառակուսի մանրապատկերների կենտրոնացված ցանցում։',
    'Sidebar + Horizontal Gallery' => 'Կողային վահանակ + հորիզոնական պատկերասրահ',
    'Vertical menu on the left; large photos scroll sideways with project names below.' => 'Ուղղահայաց մենյու ձախում. մեծ լուսանկարներ կողային ոլորումով՝ նախագծերի անվանումները ներքևում։',
    'Dark Sidebar + Horizontal Strip' => 'Մուգ կողային վահանակ + հորիզոնական ժապավեն',
    'Dark background; vertical menu on the left, full-height photos scrolling sideways.' => 'Մուգ ֆոն. ուղղահայաց մենյու ձախում, ամբողջ բարձրությամբ լուսանկարներ կողային ոլորումով։',
    'Sidebar + Horizontal Strip' => 'Կողային վահանակ + հորիզոնական ժապավեն',
    'Light background; vertical menu on the left, photos in a plain sideways-scrolling strip.' => 'Բաց ֆոն. ուղղահայաց մենյու ձախում, լուսանկարներ պարզ կողային ոլորվող ժապավենով։',
    'Sidebar + Wall' => 'Կողային վահանակ + պատ',
    'Vertical menu on the left; photos of varying heights stacked uncropped in columns.' => 'Ուղղահայաց մենյու ձախում. տարբեր բարձրությունների լուսանկարներ՝ չկտրված, սյունակներով։',
    'Staggered Gallery' => 'Շեղված պատկերասրահ',
    'Name and menu centred; uncropped photos in varying widths and offsets with generous space.' => 'Անունը և մենյուն կենտրոնում. չկտրված լուսանկարներ տարբեր լայնություններով և շեղումներով՝ առատ տարածությամբ։',
    'One Large, Two Small' => 'Մեկ մեծ, երկու փոքր',
    'Name and a “Menu” button on top; blocks of one large and two small photos, the large one alternating sides.' => 'Անունը և «Մենյու» կոճակը վերևում. բլոկներ՝ մեկ մեծ և երկու փոքր լուսանկարով, մեծը հերթով փոխում է կողմը։',
    'Sidebar + Featured' => 'Կողային վահանակ + առանձնացված',
    'Vertical menu on the left; the latest work large and uncropped, the rest as small squares below.' => 'Ուղղահայաց մենյու ձախում. վերջին աշխատանքը մեծ և չկտրված, մնացածը՝ փոքր քառակուսիներով ներքևում։',
    'Statement + Wall' => 'Տեքստ + պատ',
    'Name and a “Menu” button on top; a large intro sentence, then uncropped photos in two columns.' => 'Անունը և «Մենյու» կոճակը վերևում. մեծ ներածական նախադասություն, ապա չկտրված լուսանկարներ երկու սյունակով։',
    'Zigzag Stream' => 'Զիգզագ հոսք',
    'Name and a lines menu button on top; uncropped photos flow down the page, alternating left and right.' => 'Անունը և գծերով մենյուի կոճակը վերևում. չկտրված լուսանկարները հոսում են էջով ներքև՝ հերթով ձախ և աջ։',
    'Split Screen' => 'Բաժանված էկրան',
    'Each project fills a screen: an edge-to-edge photo on one half, a large title and short text on the other.' => 'Յուրաքանչյուր նախագիծ լցնում է մեկ էկրան՝ մի կեսում եզրից եզր լուսանկար, մյուսում՝ մեծ վերնագիր և կարճ տեքստ։',
    'Magazine Stories' => 'Ամսագրային պատմություններ',
    'Magazine pages on paper: a framed photo on a tinted panel, a light title and text beside it.' => 'Ամսագրի էջեր թղթի վրա՝ շրջանակված լուսանկար երանգավորված վահանակի վրա, կողքին՝ թեթև վերնագիր և տեքստ։',
    'Three Panels' => 'Երեք վահանակ',
    'On a dark background the screen splits into three tall panels, each a project cover with its name centred.' => 'Մուգ ֆոնի վրա էկրանը բաժանվում է երեք բարձր վահանակի, յուրաքանչյուրը՝ նախագծի շապիկ՝ անվանումը կենտրոնում։',
    'Section Banners' => 'Բաժինների բաներներ',
    'Name and a menu button on top; each menu section is a wide banner with a cover photo, large title and an arrow.' => 'Անունը և մենյուի կոճակը վերևում. մենյուի յուրաքանչյուր բաժին լայն բաներ է՝ շապիկի լուսանկարով, մեծ վերնագրով և սլաքով։',
    'Light Table' => 'Լուսային սեղան',
    'One large photo on a dark background with a vertical thumbnail strip on the right; click a thumbnail to change the photo.' => 'Մեկ մեծ լուսանկար մուգ ֆոնի վրա՝ աջում մանրապատկերների ուղղահայաց ժապավենով. լուսանկարը փոխելու համար սեղմեք մանրապատկերին։',
    'Fullscreen + Bottom Bar' => 'Ամբողջ էկրան + ներքևի տող',
    'The photo fills the whole screen; on the homepage the name and menu sit in a thin bar at the bottom.' => 'Լուսանկարը լցնում է ամբողջ էկրանը. գլխավոր էջում անունը և մենյուն գտնվում են ներքևի բարակ տողում։',
    'Background' => 'Ֆոն',
    'Site identity' => 'Կայքի ինքնություն',
    'Symbol + text' => 'Խորհրդանիշ + տեքստ',
    'Full logo' => 'Ամբողջական լոգո',
    'Symbol only' => 'Միայն խորհրդանիշ',
    'Subtitle under the name' => 'Ենթավերնագիր անվան տակ',
    'Menu layout' => 'Մենյուի դասավորություն',
    'Top, right' => 'Վերևում, աջ',
    'Top, centred' => 'Վերևում, կենտրոնում',
    'Centred under the name' => 'Կենտրոնում՝ անվան տակ',
    'Top, left' => 'Վերևում, ձախ',
