    'Home' => 'Գլխավոր',
    'Blog / Articles / News' => 'Բլոգ / Հոդվածներ / Նորություններ',
    'About Page' => '«Իմ մասին» էջ',
    'Field Routes (Map)' => 'Դաշտային երթուղիներ (քարտեզ)',
