    'Privacy notice' => 'Գաղտնիության ծանուցում',
    'Explicit consent' => 'Բացահայտ համաձայնություն',
    'New Exhibition in Preparation' => 'Պատրաստվում է նոր ցուցահանդես',
    'Our visual archive and new documentary photography projects are currently being updated. We will be back online shortly.' => 'Մեր տեսողական արխիվը և նոր վավերագրական լուսանկարչական նախագծերը թարմացվում են։ Շուտով կվերադառնանք։',
    ') Edit Language' => ') Խմբագրել լեզուն',
    ') no faulty warning text was found.' => ') սխալ նախազգուշացման տեքստ չի հայտնաբերվել։',
    ') is already filled. Overwrite it with the source-language text?' => ') արդեն լրացված է։ Փոխարինե՞լ աղբյուր լեզվի տեքստով',
    '28px - Headline' => '28px - Գլխավոր վերնագիր',
    'Align Center' => 'Կենտրոնացնել',
    'Subheading' => 'Ենթավերնագիր',
    'Subheading (H3)' => 'Ենթավերնագիր (H3)',
    'Caption' => 'Մակագիր',
    'Quote' => 'Մեջբերում',
    'Main Heading (H2)' => 'Գլխավոր վերնագիր (H2)',
